# -*- coding: utf-8 */
"""說明與科普類文章（122 篇）。

訓練重點：分辨「這件事是怎麼發生的」，而不是「發生了什麼」。
這一類最容易出現在自然與生活科技單元，答案往往有明確的因果關係，
所以題目多半要求學生找出原因、機制或條件，而不是背下結論。

涵蓋主題（依 108 課綱說明文分類）：

自然與科學：天氣、天文、地球科學、物理、化學

動物與植物

人體與健康

生活與應用：物品原理、實用技能、飲食與烹飪

地球與環境

社會與文化：制度、節慶、文化

科技與資訊：科技應用、資訊素養

歷史與制度

每一篇都是十題的漸進提問（1-3 細節理解、4-7 推論分析、8-10 省思評鑑）。
"""

